+                    .hasStackTraceContaining("app.staleness.max-age must be at least 1 day");
+        });
+    }
+
+    @Configuration(proxyBeanMethods = false)
+    @EnableConfigurationProperties(StalenessProperties.class)
+    static class EnableStaleness {
+    }
+}
